import{_ as o,o as d,c as s,a3 as a}from"./chunks/framework.BTQ4eCVb.js";const k=JSON.parse('{"title":"Tenant API v1 — Help Desk","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Help Desk | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-help-desk"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Help Desk | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-help-desk"}]]},"headers":[],"relativePath":"api/tenant-v1-help-desk.md","filePath":"api/tenant-v1-help-desk.md","lastUpdated":1788479753000}'),t={name:"api/tenant-v1-help-desk.md"};function i(c,e,l,n,r,p){return d(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="tenant-api-v1-—-help-desk" tabindex="-1">Tenant API v1 — Help Desk <a class="header-anchor" href="#tenant-api-v1-—-help-desk" aria-label="Permalink to &quot;Tenant API v1 — Help Desk&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>module:help-desk</code>, plus permission middleware / policies.</p><p>No hard <code>module_dependencies</code> — Help Desk installs standalone. <code>contact_id</code> and <code>company_id</code> are optional; supplying either requires the corresponding module (<code>contacts</code> / <code>companies</code>) to be entitled on the workspace, enforced by <code>LinkableContact</code> / <code>LinkableCompany</code>.</p><p>Assignee scoping: without <code>help-desk.assign</code> (and not superadmin), list/board/stats/view/update/<strong>close</strong>/<strong>reopen</strong> only include tickets where <code>assigned_to</code> is the current user.</p><h2 id="stats-board" tabindex="-1">Stats &amp; board <a class="header-anchor" href="#stats-board" aria-label="Permalink to &quot;Stats &amp; board&quot;">​</a></h2><h3 id="get-help-desk-stats" tabindex="-1">GET <code>/help-desk/stats</code> <a class="header-anchor" href="#get-help-desk-stats" aria-label="Permalink to &quot;GET `/help-desk/stats`&quot;">​</a></h3><p>Same filters as list (minus pagination/sort). Response:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;total_tickets&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;my_tickets&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;open&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;in_progress&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;waiting&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;resolved&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;closed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;overdue&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;sla_breached&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;sla_at_risk&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;scope&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;org | mine&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>overdue</code> counts tickets in <code>open</code>, <code>in_progress</code>, or <code>waiting</code> with <code>due_at</code> before now (UTC instant comparison). <code>sla_breached</code> / <code>sla_at_risk</code> use SLA clock columns (<code>UtcInstant</code>); at-risk means due within the next hour and not yet breached.</p><h3 id="get-help-desk-board" tabindex="-1">GET <code>/help-desk/board</code> <a class="header-anchor" href="#get-help-desk-board" aria-label="Permalink to &quot;GET `/help-desk/board`&quot;">​</a></h3><p>One column per status (<code>open</code>, <code>in_progress</code>, <code>waiting</code>, <code>resolved</code>, <code>closed</code>): <code>status</code>, <code>label</code>, <code>ticket_count</code>, <code>tickets[]</code>. Honors the same filters as list (including assignee scoping). Optional <code>per_column</code> (1–100, default 50). Fixed enum columns — same pattern as Tasks, not Opportunities stages.</p><h2 id="tickets-crud" tabindex="-1">Tickets CRUD <a class="header-anchor" href="#tickets-crud" aria-label="Permalink to &quot;Tickets CRUD&quot;">​</a></h2><h3 id="get-help-desk" tabindex="-1">GET <code>/help-desk</code> <a class="header-anchor" href="#get-help-desk" aria-label="Permalink to &quot;GET `/help-desk`&quot;">​</a></h3><p>Query: <code>search</code> (matches <code>subject</code>, <code>number</code>, or <code>description</code>), <code>status</code> (<code>open</code>|<code>in_progress</code>|<code>waiting</code>|<code>resolved</code>|<code>closed</code>), <code>priority</code> (<code>low</code>|<code>medium</code>|<code>high</code>|<code>urgent</code>), <code>category_id</code>, <code>contact_id</code>, <code>company_id</code>, <code>assigned_to</code> (<code>unassigned</code> or user id), <code>my_tickets</code>, <code>overdue</code>, <code>sla_breached</code> (<code>1</code> / <code>true</code> / <code>response</code> / <code>resolve</code>), <code>sla_at_risk</code>, <code>trashed</code> (<code>true</code>|<code>only</code>), <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><p>List items include <code>status</code>, <code>priority</code>, <code>source</code> (<code>manual</code>|<code>email</code>), SLA clock fields (<code>sla_policy_id</code>, <code>first_responded_at</code>, <code>sla_response_due_at</code>, <code>sla_resolve_due_at</code>, <code>sla_response_breached_at</code>, <code>sla_resolve_breached_at</code>), embedded <code>sla_policy</code> / <code>category</code>, <code>due_at</code>, contact/company refs (when linked), <code>knowledge_base_articles</code> summary, assignee/creator refs, and <code>latest_note</code>.</p><h3 id="post-help-desk" tabindex="-1">POST <code>/help-desk</code> <a class="header-anchor" href="#post-help-desk" aria-label="Permalink to &quot;POST `/help-desk`&quot;">​</a></h3><p>Body: <code>subject</code> (required), <code>description</code> (optional), <code>priority</code> (optional, default <code>medium</code>), <code>category_id</code> (optional — tenant <code>help_desk_categories</code> id, must be active; defaults to seeded <strong>Other</strong>), <code>contact_id</code> (optional — Contacts module must be entitled), <code>company_id</code> (optional — Companies module must be entitled), <code>knowledge_base_article_ids</code> (optional <code>int[]</code> — Knowledge Base module must be entitled; each id validated via <code>LinkableKnowledgeBaseArticle</code>: published for view-only actors, or draft/archived when actor has <code>knowledge-base.update</code>), <code>due_at</code> (optional ISO datetime), <code>assigned_to</code> (optional — requires actor to hold <code>help-desk.assign</code>; otherwise defaults to creator).</p><p>Status always starts at <code>open</code>; <code>number</code> is auto-generated (<code>HD-00001</code>, configurable via <code>help_desk_number_prefix</code> tenant setting).</p><h3 id="get-help-desk-id" tabindex="-1">GET <code>/help-desk/{id}</code> <a class="header-anchor" href="#get-help-desk-id" aria-label="Permalink to &quot;GET `/help-desk/{id}`&quot;">​</a></h3><p>Includes category, contact, company, assignee, creator, <code>knowledge_base_articles</code> (when KB entitled), notes, and timeline activities. Contact refs include <code>email</code> / <code>phone</code> when present (for soft-gated Communication Template WhatsApp). Embedded <code>notes</code> and timeline/domain <code>activities</code> are <strong>newest-first</strong> (<code>created_at</code> DESC, then <code>id</code> DESC).</p><h3 id="put-help-desk-id" tabindex="-1">PUT <code>/help-desk/{id}</code> <a class="header-anchor" href="#put-help-desk-id" aria-label="Permalink to &quot;PUT `/help-desk/{id}`&quot;">​</a></h3><p>Partial update of non-<strong>closed</strong> tickets only. Closed tickets return 422 (<code>Closed tickets cannot be edited.</code>). Accepts <code>knowledge_base_article_ids</code> (same rules as create). Assignment after create uses <code>POST /help-desk/{id}/assign</code>.</p><h3 id="delete-help-desk-id" tabindex="-1">DELETE <code>/help-desk/{id}</code> <a class="header-anchor" href="#delete-help-desk-id" aria-label="Permalink to &quot;DELETE `/help-desk/{id}`&quot;">​</a></h3><p>Soft delete. Permission: <code>help-desk.delete</code>.</p><h3 id="post-help-desk-id-restore" tabindex="-1">POST <code>/help-desk/{id}/restore</code> <a class="header-anchor" href="#post-help-desk-id-restore" aria-label="Permalink to &quot;POST `/help-desk/{id}/restore`&quot;">​</a></h3><p>Permission: <code>help-desk.restore</code>.</p><h3 id="delete-help-desk-id-force" tabindex="-1">DELETE <code>/help-desk/{id}/force</code> <a class="header-anchor" href="#delete-help-desk-id-force" aria-label="Permalink to &quot;DELETE `/help-desk/{id}/force`&quot;">​</a></h3><p>Permanently delete a soft-deleted ticket. Permission: <code>help-desk.force.delete</code> (owner/superadmin only by default).</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><h3 id="post-help-desk-id-assign" tabindex="-1">POST <code>/help-desk/{id}/assign</code> <a class="header-anchor" href="#post-help-desk-id-assign" aria-label="Permalink to &quot;POST `/help-desk/{id}/assign`&quot;">​</a></h3><p><code>{ &quot;assigned_to&quot;: number|null }</code></p><p>Permission: <code>help-desk.assign</code>.</p><h3 id="post-help-desk-id-close" tabindex="-1">POST <code>/help-desk/{id}/close</code> <a class="header-anchor" href="#post-help-desk-id-close" aria-label="Permalink to &quot;POST `/help-desk/{id}/close`&quot;">​</a></h3><p>Transitions to <code>closed</code> from <code>open</code>, <code>in_progress</code>, <code>waiting</code>, or <code>resolved</code>. Permission: <code>help-desk.close</code> (assignee-scoped unless the actor has <code>help-desk.assign</code> or is superadmin).</p><h3 id="post-help-desk-id-reopen" tabindex="-1">POST <code>/help-desk/{id}/reopen</code> <a class="header-anchor" href="#post-help-desk-id-reopen" aria-label="Permalink to &quot;POST `/help-desk/{id}/reopen`&quot;">​</a></h3><p>Transitions to <code>open</code> from <code>resolved</code> or <code>closed</code>. Permission: <code>help-desk.reopen</code> (assignee-scoped unless the actor has <code>help-desk.assign</code> or is superadmin).</p><h3 id="post-help-desk-id-status" tabindex="-1">POST <code>/help-desk/{id}/status</code> <a class="header-anchor" href="#post-help-desk-id-status" aria-label="Permalink to &quot;POST `/help-desk/{id}/status`&quot;">​</a></h3><p><code>{ &quot;status&quot;: &quot;open&quot;|&quot;in_progress&quot;|&quot;waiting&quot;|&quot;resolved&quot;|&quot;closed&quot; }</code></p><p>Permission: <code>help-desk.update</code>. Rejects disallowed transitions with a 422 validation error on <code>status</code>. Records a <code>status_changed</code> timeline entry. Prefer explicit <code>close</code> / <code>reopen</code> when those semantics apply (they use dedicated permissions).</p><h3 id="post-help-desk-id-notes" tabindex="-1">POST <code>/help-desk/{id}/notes</code> <a class="header-anchor" href="#post-help-desk-id-notes" aria-label="Permalink to &quot;POST `/help-desk/{id}/notes`&quot;">​</a></h3><p><code>{ &quot;body&quot;: string }</code></p><p>Permission: <code>help-desk.update</code>.</p><h3 id="get-help-desk-id-timeline" tabindex="-1">GET <code>/help-desk/{id}/timeline</code> <a class="header-anchor" href="#get-help-desk-id-timeline" aria-label="Permalink to &quot;GET `/help-desk/{id}/timeline`&quot;">​</a></h3><p>Domain timeline entries (<code>created</code>, <code>updated</code>, <code>assigned</code>, <code>status_changed</code>, <code>note_added</code>, <code>articles_synced</code>, <code>deleted</code>, <code>restored</code>).</p><h3 id="put-help-desk-id-articles" tabindex="-1">PUT <code>/help-desk/{id}/articles</code> <a class="header-anchor" href="#put-help-desk-id-articles" aria-label="Permalink to &quot;PUT `/help-desk/{id}/articles`&quot;">​</a></h3><p><code>{ &quot;article_ids&quot;: number[] }</code> — replace linked Knowledge Base articles (same validation as <code>knowledge_base_article_ids</code>). Permission: <code>help-desk.update</code>. Records <code>articles_synced</code> when the set changes.</p><h2 id="help-desk-categories" tabindex="-1">Help desk categories <a class="header-anchor" href="#help-desk-categories" aria-label="Permalink to &quot;Help desk categories&quot;">​</a></h2><p>Categories use the same <code>module:help-desk</code> gate and <code>help-desk.*</code> permissions (no separate permission family). Listing lazy-seeds General / Technical / Billing / Account / Other when missing. Starter slugs (<code>general|technical|billing|account|other</code>) are not changed on rename. Listing does not restore a soft-deleted starter except <strong>Other</strong>.</p><ul><li><code>GET /help-desk-categories</code> — list (<code>help-desk.view</code>)</li><li><code>POST /help-desk-categories</code> — create (<code>help-desk.create</code>). Body: <code>name</code> (required); optional <code>slug</code>, <code>sort_order</code>, <code>is_active</code></li><li><code>GET|PUT|DELETE /help-desk-categories/{helpDeskCategory}</code> — view, update, soft-delete (<code>view</code> / <code>update</code> / <code>delete</code>)</li><li><code>POST /help-desk-categories/{helpDeskCategory}/restore</code> — restore (<code>help-desk.restore</code>)</li><li><code>DELETE /help-desk-categories/{helpDeskCategory}/force</code> — permanently delete a soft-deleted category (<code>help-desk.force.delete</code>)</li></ul><p>Delete and force-delete return 422 if the category slug is <code>other</code>, or if any tickets (including trashed, for force) still reference the category.</p><h2 id="sla-policies-1-3-0" tabindex="-1">SLA policies (1.3.0) <a class="header-anchor" href="#sla-policies-1-3-0" aria-label="Permalink to &quot;SLA policies (1.3.0)&quot;">​</a></h2><p>Same <code>module:help-desk</code> gate and <code>help-desk.*</code> permissions (no separate family).</p><ul><li><code>GET /help-desk-sla-policies</code> — list (<code>help-desk.view</code>)</li><li><code>POST /help-desk-sla-policies</code> — create (<code>help-desk.create</code>). Body: <code>name</code> (required); <code>first_response_minutes</code>, <code>resolve_minutes</code> (required integers ≥ 1); optional <code>category_id</code>, <code>priority</code> (<code>null</code> = any), <code>is_active</code></li><li><code>GET|PUT|DELETE /help-desk-sla-policies/{helpDeskSlaPolicy}</code> — view / update / soft-delete</li><li><code>POST …/restore</code>, <code>DELETE …/force</code> — restore / force-delete</li></ul><p>Policy matching on ticket create (and open priority/category change): category+priority &gt; priority-only &gt; category-only &gt; default (both null). Breach scan: <code>php artisan help-desk:scan-sla-breaches</code>.</p><h2 id="shared-mailboxes-email-intake-1-4-0" tabindex="-1">Shared mailboxes / email intake (1.4.0) <a class="header-anchor" href="#shared-mailboxes-email-intake-1-4-0" aria-label="Permalink to &quot;Shared mailboxes / email intake (1.4.0)&quot;">​</a></h2><p>Dedicated IMAP support mailboxes (not personal Email module accounts). Passwords are encrypted at rest and never returned in resources (<code>has_password</code> boolean only).</p><ul><li><code>GET /help-desk/mailboxes</code> — list (<code>help-desk.view</code>)</li><li><code>POST /help-desk/mailboxes</code> — create (<code>help-desk.create</code>). Body: <code>name</code>, <code>address</code>, <code>imap_host</code>, <code>imap_port</code>, <code>imap_encryption</code> (<code>ssl</code>|<code>tls</code>|<code>none</code>), <code>imap_username</code>, <code>imap_password</code>, optional <code>is_active</code></li><li><code>GET|PUT|DELETE /help-desk/mailboxes/{helpDeskMailbox}</code> — view / update / delete (<code>view</code> / <code>update</code> / <code>delete</code>)</li><li><code>POST /help-desk/mailboxes/{helpDeskMailbox}/test</code> — test IMAP (<code>help-desk.update</code>)</li><li><code>POST /help-desk/mailboxes/{helpDeskMailbox}/sync</code> — dispatch <code>SyncHelpDeskMailboxJob</code> on queue <code>help-desk-ingest</code> (<code>help-desk.update</code>)</li></ul><p>Scheduler: <code>help-desk:sync-mailboxes</code> every minute. Inbound without a ticket number creates <code>source=email</code> tickets; subject/body matching <code>{prefix}\\d{5,}</code> appends an unauthored note.</p>',59)])])}const u=o(t,[["render",i]]);export{k as __pageData,u as default};
